import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { productsAPI } from '../services/api';

const ProductDetail = ({ addToCart, showNotification }) => {
  const { id } = useParams();
  const [product, setProduct] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isFavorite, setIsFavorite] = useState(false);

  useEffect(() => {
    const fetchProduct = async () => {
      try {
        const response = await productsAPI.getById(id);
        setProduct(response.data);

        // Check if product is in favorites
        const favorites = JSON.parse(localStorage.getItem('favorites') || '[]');
        setIsFavorite(favorites.some(fav => fav._id === response.data._id));
      } catch (error) {
        console.error('Error fetching product:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchProduct();
  }, [id]);

  const toggleFavorite = () => {
    const token = localStorage.getItem('token');
    if (!token) {
      showNotification('Please login to add favorites', 'info');
      return;
    }

    let favorites = JSON.parse(localStorage.getItem('favorites') || '[]');

    if (isFavorite) {
      favorites = favorites.filter(fav => fav._id !== product._id);
      setIsFavorite(false);
      showNotification('Removed from favorites', 'info');
    } else {
      favorites.push(product);
      setIsFavorite(true);
      showNotification('Added to favorites!', 'success');
    }

    localStorage.setItem('favorites', JSON.stringify(favorites));
  };

  const handleBuyNow = async () => {
    const token = localStorage.getItem('token');
    if (!token) {
      showNotification('Please login to buy products', 'info');
      return;
    }

    const address = prompt('Enter shipping address:');
    const phone = prompt('Enter phone number:');

    if (address && phone) {
      try {
        await productsAPI.buyNow(product._id, {
          quantity: 1,
          shippingAddress: address,
          phoneNumber: phone
        });
        showNotification('Order placed successfully!', 'success');
      } catch (error) {
        showNotification('Error placing order: ' + (error.response?.data?.message || 'Unknown error'), 'error');
      }
    }
  };

  if (loading) return <div className="loading">Loading product details...</div>;
  if (!product) return <div className="container">Product not found</div>;

  return (
    <div className="container">
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '2rem' }}>
        <div>
          <img 
            src={product.image || 'https://via.placeholder.com/400x300'} 
            alt={product.name}
            style={{ width: '100%', borderRadius: '8px' }}
          />
        </div>
        <div>
          <h1>{product.name}</h1>
          <p className="price" style={{ fontSize: '2rem', margin: '1rem 0' }}>
            ₹{product.price}
          </p>
          <p style={{ marginBottom: '1rem' }}>{product.description}</p>
          <p><strong>Category:</strong> {product.category}</p>
          <p><strong>Seller:</strong> {product.seller?.name}</p>
          <p><strong>Stock:</strong> {product.stock} available</p>
          <p><strong>Likes:</strong> {product.likes?.length || 0}</p>

          <div style={{ display: 'flex', gap: '1rem', marginTop: '2rem', flexWrap: 'wrap' }}>
            <button 
              onClick={() => {
                addToCart(product);
                showNotification('Product added to cart!', 'success');
              }} 
              className="btn"
              disabled={product.stock === 0}
            >
              {product.stock === 0 ? 'Out of Stock' : 'Add to Cart'}
            </button>

            <button 
              onClick={handleBuyNow}
              className="btn btn-success"
              disabled={product.stock === 0}
            >
              Buy Now
            </button>

            <button 
              onClick={toggleFavorite}
              className={`btn ${isFavorite ? 'btn-danger' : 'btn-secondary'}`}
            >
              {isFavorite ? '❤️' : '🤍'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProductDetail;
